"""Local preview with the same contract as production hosting.

* Security and cache headers come from dist/_headers (generated by build.mjs from site.config.mjs),
  so the preview sends exactly what Netlify, Cloudflare Pages and the nginx image send.
* Pre-compressed .br / .gz files are served when the browser accepts them.
* Unknown paths return the custom 404 page with HTTP status 404.
"""
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote, urlsplit
import fnmatch
import os

DIST = Path('dist')
EXTRA_TYPES = {'.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
               '.webmanifest': 'application/manifest+json', '.txt': 'text/plain; charset=utf-8', '.xml': 'application/xml; charset=utf-8'}


def load_rules():
    rules, current = [], None
    for line in (DIST / '_headers').read_text().splitlines():
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        if not line.startswith((' ', '\t')):
            current = (line.strip(), {})
            rules.append(current)
        elif current and ':' in line:
            key, value = line.strip().split(':', 1)
            current[1][key.strip()] = value.strip()
    return rules


class Handler(SimpleHTTPRequestHandler):
    rules = load_rules()
    extensions_map = {**SimpleHTTPRequestHandler.extensions_map, **EXTRA_TYPES}

    def __init__(self, *args, **kwargs):
        super().__init__(*args, directory=str(DIST), **kwargs)

    def headers_for(self, path):
        merged = {}
        for pattern, values in self.rules:   # later, more specific rules override earlier ones
            if fnmatch.fnmatchcase(path, pattern):
                merged.update(values)
        return merged

    def end_headers(self):
        path = unquote(urlsplit(self.path).path)
        for key, value in self.headers_for(path).items():
            self.send_header(key, value)
        super().end_headers()

    def send_head(self):
        path = unquote(urlsplit(self.path).path)
        if path == '/_headers':   # host configuration is never served
            self.send_error(404)
            return None
        local = Path(self.translate_path(self.path))
        if local.is_dir() and path.endswith('/'):
            local = local / 'index.html'
        accepted = self.headers.get('Accept-Encoding', '')
        for encoding, suffix in (('br', '.br'), ('gzip', '.gz')):
            candidate = local.with_name(local.name + suffix)
            if local.is_file() and encoding in accepted and candidate.is_file():
                data = candidate.read_bytes()
                self.send_response(200)
                self.send_header('Content-Type', self.guess_type(str(local)))
                self.send_header('Content-Encoding', encoding)
                self.send_header('Content-Length', str(len(data)))
                self.send_header('Vary', 'Accept-Encoding')
                self.end_headers()
                return _Body(data)
        return super().send_head()

    def send_error(self, code, message=None, explain=None):
        if code != 404:
            return super().send_error(code, message, explain)
        page = (DIST / '404.html').read_bytes()
        self.send_response(404)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Content-Length', str(len(page)))
        self.end_headers()
        if self.command != 'HEAD':
            self.wfile.write(page)


class _Body:
    """File-like wrapper so SimpleHTTPRequestHandler can copy an in-memory body."""
    def __init__(self, data):
        self.data = data
    def read(self, *_):
        data, self.data = self.data, b''
        return data
    def close(self):
        pass


port = int(os.environ.get('PORT', '4173'))
print(f'Snag preview: http://localhost:{port}', flush=True)
ThreadingHTTPServer(('127.0.0.1', port), Handler).serve_forever()
